from collections import deque


class RateLimiter:
    def __init__(self, limit, window, clock):
        if type(limit) is not int or limit < 1:
            raise ValueError("Limit must be positive")
        if type(window) not in (int, float) or window <= 0:
            raise ValueError("Window must be positive")
        self._limit = limit
        self._window = window
        self._clock = clock
        self._log = {}

    def _live(self, key, now):
        log = self._log.get(key)
        if log is None:
            return deque()
        cutoff = now - self._window
        while log and log[0] <= cutoff:
            log.popleft()
        if not log:
            del self._log[key]
        return log

    def allow(self, key):
        now = self._clock()
        log = self._live(key, now)
        if len(log) >= self._limit:
            return False
        self._log.setdefault(key, log).append(now)
        return True

    def remaining(self, key):
        return self._limit - len(self._live(key, self._clock()))

    def retry_after(self, key):
        now = self._clock()
        log = self._live(key, now)
        if len(log) < self._limit:
            return 0
        return log[0] + self._window - now

    def reset(self, key):
        self._log.pop(key, None)

    @property
    def tracked(self):
        now = self._clock()
        for key in list(self._log):
            self._live(key, now)
        return len(self._log)
